	inline std::string Url(const char* assetId)
	{
		if (!assetId || !assetId[0])
			return "";
		return std::string("http://www.roblox.com/asset/?id=") + assetId;
	}

	inline const char* SlotName(int slot)
	{
		const auto& p = Packs();
		if (slot == 0 || slot > (int)p.size())
			return "Custom";
		return p[slot - 1].Name;
	}

	inline int SlotCount()
	{
		return (int)Packs().size() + 1;
	}
